export default function mitt<Events extends Record<EventType, unknown>>(
	all?: EventHandlerMap<Events>
): Emitter<Events> {

all = all || new Map();

return {
	/**
	 * A Map of event names to registered handler functions.
	 */
	all,

	/**
	 * Register an event handler for the given type.
	 * @param {string|symbol} type Type of event to listen for, or `'*'` for all events
	 * @param {Function} handler Function to call in response to given event
	 * @memberOf mitt
	 */

describe('mitt', () => {
	it('should default export be a function', () => {
		expect(mitt).to.be.a('function');
	});

	it('should accept an optional event handler map', () => {
		expect(() => mitt(new Map())).not.to.throw;
		const map = new Map();
		const a = spy();
		const b = spy();
		map.set('foo', [a, b]);
		const events = mitt<{ foo: undefined }>(map);
		events.emit('foo');
		expect(a).to.have.been.calledOnce;
		expect(b).to.have.been.calledOnce;
	});
});

let events: EventHandlerMap<Events>, inst: Emitter<Events>;

beforeEach(() => {
	events = new Map();
	inst = mitt(events);
});

/**
 * Mitt: Tiny (~200b) functional event emitter / pubsub.
 * @name mitt
 * @returns {Mitt}
 */

import mitt, { Emitter, EventHandlerMap } from '..';
import chai, { expect } from 'chai';
import { spy } from 'sinon';
import sinonChai from 'sinon-chai';
chai.use(sinonChai);

emit<Key extends keyof Events>(type: Key, evt?: Events[Key]) {
	let handlers = all!.get(type);
	if (handlers) {
		(handlers as EventHandlerList<Events[keyof Events]>)
			.slice()
			.map((handler) => {
				handler(evt!);
			});
	}

	handlers = all!.get('*');
	if (handlers) {
		(handlers as WildCardEventHandlerList<Events>)
			.slice()
			.map((handler) => {
				handler(type, evt!);
			});
	}
}

describe('properties', () => {
	it('should expose the event handler map', () => {
		expect(inst).to.have.property('all').that.is.a('map');
	});
});

### Typescript

Set `"strict": true` in your tsconfig.json to get improved type inference for `mitt` instance methods.

```ts
import mitt from 'mitt';

type Events = {
  foo: string;
  bar?: number;
};

const emitter = mitt<Events>(); // inferred as Emitter<Events>

emitter.on('foo', (e) => {}); // 'e' has inferred type 'string'

emitter.emit('foo', 42); // Error: Argument of type 'number' is not assignable to parameter of type 'string'. (2345)
```

Alternatively, you can use the provided `Emitter` type:

```ts
import mitt, { Emitter } from 'mitt';

type Events = {
  foo: string;
  bar?: number;
};

const emitter: Emitter<Events> = mitt<Events>();
```

## Usage

```js
import mitt from 'mitt'

const emitter = mitt()

// listen to an event
emitter.on('foo', e => console.log('foo', e) )

// listen to all events
emitter.on('*', (type, e) => console.log(type, e) )

// fire an event
emitter.emit('foo', { a: 'b' })

// clearing all events
emitter.all.clear()

// working with handler references:
function onFoo() {}
emitter.on('foo', onFoo)   // listen
emitter.off('foo', onFoo)  // unlisten
```
